// Astro configuration for the conan-flake documentation site.
//
// The site is generated by Astro with the Starlight documentation theme, from
// the Markdown sources under `src/content/docs`.
//
// site.BUILD.2
// site.SOURCES.1
import { defineConfig } from "astro/config";
import starlight from "@astrojs/starlight";

import rehypeRewriteLinks from "./plugins/rehype-rewrite-links.mjs";

// The site is served from a sub-path of the host
// (`https://tarcisio.codeberg.page/conan-flake/`), so every internal link,
// asset reference and search resource has to be emitted below it. Astro builds
// them all from `base`; the rehype plugin below uses the same value for the
// links the Markdown sources spell as `./<chapter>.md`.
//
// site.NAVIGATION.3
const base = "/conan-flake";

export default defineConfig({
  site: "https://tarcisio.codeberg.page",
  base,

  markdown: {
    rehypePlugins: [[rehypeRewriteLinks, { base }]],
  },

  // Astro caches into `node_modules/.astro` and Vite pre-bundles into
  // `node_modules/.vite` by default. Both are moved here under `.astro/`, the
  // one git-ignored working directory of this project: `node_modules` holds
  // the dependency tree the development shell installs from the Nix store, and
  // is replaced wholesale whenever that tree changes.
  cacheDir: "./.astro/cache",

  vite: {
    cacheDir: "./.astro/vite",

    server: {
      // The changelog chapter renders `CHANGELOG.md` from the repository root,
      // which is outside this Astro project; the development server refuses to
      // read such a file unless it is allowed explicitly.
      //
      // site.GUIDES.9
      fs: { allow: [".."] },
    },
  },

  integrations: [
    starlight({
      title: "conan-flake",
      description:
        "A module to ease the integration of the Conan C/C++ package manager in the Nix ecosystem",

      editLink: {
        // Starlight appends the source file's path relative to this Astro
        // project (`docs/`), so the base has to end at `docs/`.
        baseUrl: "https://codeberg.org/tarcisio/conan-flake/_edit/main/docs/",
      },

      social: [
        {
          icon: "codeberg",
          label: "Codeberg",
          href: "https://codeberg.org/tarcisio/conan-flake",
        },
      ],

      // Starlight renders this list into the sidebar of every page, so a page
      // that is not named here is not reachable from the site's navigation.
      //
      // site.NAVIGATION.1
      sidebar: [
        { label: "conan-flake", link: "/" },
        { label: "Getting started", slug: "getting-started" },
        { label: "flake-parts", slug: "flake-parts" },
        { label: "devenv", slug: "devenv" },
        {
          label: "Standalone",
          items: [
            { label: "Standalone", slug: "standalone" },
            { label: "evalConanConfig", slug: "standalone-eval-conan-config" },
            { label: "submoduleWith", slug: "standalone-submodule-with" },
          ],
        },
        {
          label: "Toolchains",
          items: [
            { label: "Toolchains", slug: "toolchains" },
            { label: "LLVM", slug: "toolchains-llvm" },
            { label: "CUDA", slug: "toolchains-cuda" },
          ],
        },
        { label: "Templates", slug: "templates" },
        { label: "Contributing", slug: "contributing" },
        { label: "References", slug: "references" },
        { label: "Changelog", slug: "changelog" },
      ],

      // Full-text search over the site's own pages, built by Pagefind at the
      // end of the build and served from the site itself, so it keeps working
      // under a sub-path.
      //
      // site.NAVIGATION.2
      pagefind: true,
    }),
  ],
});
